      block: row.block,
      blockId: row.blockId,
      status: row.status,
      operatorDecision: 'PENDING',
      correctedPath: '',
      correctedHitPath: '',
      correctedLabelX: '',
      correctedLabelY: '',
      reviewer: '',
      reviewedAt: '',
      operatorNote: '',
      suggestedApprovalFields: row.suggestedApprovalFields,
      candidatePath: row.candidatePath,
      candidateLabelX: row.candidateLabelX,
      candidateLabelY: row.candidateLabelY,
